        // Transport failures come back as values; out-of-allowlist requests trap.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat t={seconds} fetched={fetched}");
        let notified = notifier::notify(&message);

        // ensures notified == true: a refused notification traps instead of
        // producing a report that violates the contract.
        assert!(notified, "notification not accepted");

